sp_widget.client_script:
function teleworkTicketActions($scope, $http, spUtil, $timeout, spModal, i18n, $window, $uibModal, spAriaUtil) {
    /* widget controller */
    var c = this;
    c.doneLoading = false;
    c.approvedTeleworkMsg = "${x_hccc_hoc_ohs.telework_portal_agreement_approved}";
    c.refusedTeleworkMsg = "${x_hccc_hoc_ohs.telework_portal_agreement_rejected}";
    //c.canceledTeleworkMsg = "${Telework Canceled}";

    var MOBILE_DEVICE_SCREEN_WIDTH = 767;
    $scope.mobileDevice = c.data.isMobile || ($window.innerWidth < MOBILE_DEVICE_SCREEN_WIDTH);

	$scope.approve = function() {
        $scope.data.action = 'approve';
        $scope.server.update(init).then(function(response){
					if (response.isTeleworkApproved)
						spAriaUtil.sendLiveMessage(c.approvedTeleworkMsg);
				});
		$scope.$emit('focusOnActions', {"isFocusRequired": true});
    };

	$scope.refuse = function() {
		$scope.data.action = 'refuse';
        $scope.server.update(init).then(function(response){
					if (response.isTeleworkRefused)
						spAriaUtil.sendLiveMessage(c.refusedTeleworkMsg);
				});
		var elm = document.getElementById('short-desc');
		elm.focus();
	};

    $scope.cancel = function() {
        $scope.data.action = 'cancel';
        $scope.server.update(init).then(function(response){
					if (response.isTeleworkCanceled)
						spAriaUtil.sendLiveMessage(c.canceledTeleworkMsg);
				});
			$scope.$emit('focusOnActions', {"isFocusRequired": true});
    };

    function init() {}

    $(document).on('click', 'div.modal-footer button.btn, ul#child-case-tabs .dropdown-menu', function(e) {
        e.stopPropagation();
    });

    $(document).bind('dragover drop', function(event) {
        event.preventDefault();
        return false;
    });

    $scope.$on('sp_loading_indicator', function(e, value) {
        if (!value && !c.doneLoading) {
            c.doneLoading = true;
        }
    });
}

sp_widget.css:
$sp-space--md: 12px !default;
.arrow {
  position: absolute;
  margin-left: 50px;
  z-index: 150;
  border-left: $sp-space--md solid transparent;
  border-right: $sp-space--md solid transparent;
  border-bottom: $sp-space--md solid #FFFFFF;
}

.question-tab{
	font-size:1.4rem;
}

.dropdown-menu li {
  cursor: pointer;
}

.action-btn {
  width: 100%;
}

.fa-caret-down {
  vertical-align: middle;
  font-size: 1.3rem;
}

sp_widget.link:
function link(scope, element, attrs, controller) {
  scope.setFocusOnActionButtons = function() {
		if (scope.widget.isFocusRequired) {
			var elm = element.find('#actions-button')[0];
			elm.focus();
		}
	}
}

sp_widget.script:
/* global data, $sp, input, options, HoCOHSMTelWrkUtils */
(function() {
    var teleworkUtils = new HoCOHSMTelWrkUtils();
    var teleworkGr = new GlideRecord('x_hccc_hoc_ohs_telework_agreement');
    var teleworkSysId = options.sys_id;

    if (!teleworkSysId && $sp.getParameter('table') == 'x_hccc_hoc_ohs_telework_agreement') {
        teleworkSysId = $sp.getParameter('sys_id');
    }


    if (!teleworkSysId && $sp.getParameter('table') == 'universal_request') {
        var urGr = new GlideRecord('universal_request');

        urGr.get($sp.getParameter('sys_id'));
        teleworkSysId = urGr.primary_task + "";
    }

    /* Actions - Start */
    if (input && input.action == 'approve' && teleworkGr.get(teleworkSysId)) {
        data.isTeleworkApproved = teleworkUtils.approve(teleworkGr);
    }

    if (input && input.action == 'refuse' && teleworkGr.get(teleworkSysId)) {
        data.isTeleworkRefused = teleworkUtils.refuse(teleworkGr);
    }

    /* Actions - End */

    /* Load Telework data */
    if (teleworkGr.get(teleworkSysId)) {
        data.canApprove = teleworkUtils.canApproveTeleworkAgreement(teleworkGr);
        data.canRefuse = teleworkUtils.canRejectTeleworkAgreement(teleworkGr);
        //data.canCancel = true; //incidentUtils.canCloseIncident(teleworkGr);
    }

    data.i18n = {};

})();
